// Este nodo usa dos fuentes:
// 1) Webhook Evo API = payload original de WhatsApp.
// 2) Resolver cliente/canal Streamify = datos SaaS + apikey Evo obtenida desde Streamify.
// No usa $env.

const webhookRoot = $('Webhook Evo API').first().json || {};
const body = Array.isArray(webhookRoot) ? (webhookRoot[0]?.body || webhookRoot[0]) : (webhookRoot.body || webhookRoot);

const resolved = $('Resolver cliente/canal Streamify').first().json || {};
const data = body.data || {};
const key = data.key || {};
const messagePayload = data.message || {};

const instanceName = body.instance || data.instance || resolved.channel?.instance_name || resolved.instance?.name || '';
const instanceId = data.instanceId || resolved.channel?.instance_id || null;
const serverUrl = resolved.channel?.server_url || resolved.instance?.server_url || body.server_url || body.serverUrl || body.serverURL || '';
const evoApiKey = resolved.channel?.apikey || resolved.channel?.api_key || resolved.instance?.apikey || resolved.instance?.api_key || resolved.evo_apikey || '';

const event = body.event || '';
const remoteJid = key.remoteJid || key.remoteJidAlt || '';
const remoteJidAlt = key.remoteJidAlt || null;

const isGroup = String(remoteJid).endsWith('@g.us');
const groupJid = isGroup ? remoteJid : null;

const participantJid =
  key.participantAlt ||
  key.participant ||
  data.contextInfo?.participant ||
  null;

const customerJid = isGroup ? (participantJid || remoteJid) : remoteJid;
const senderIdentifier = String(customerJid || '').split('@')[0] || '';

const fromMe = Boolean(key.fromMe);
const providerMessageId = key.id || null;
const pushName = data.pushName || resolved.final_customer?.name || 'Cliente';
const messageTimestamp = data.messageTimestamp || null;

let messageType = data.messageType || 'unknown';

let contentText =
  messagePayload.conversation ||
  messagePayload.extendedTextMessage?.text ||
  messagePayload.imageMessage?.caption ||
  messagePayload.videoMessage?.caption ||
  messagePayload.documentMessage?.caption ||
  '';

let captionText =
  messagePayload.imageMessage?.caption ||
  messagePayload.videoMessage?.caption ||
  messagePayload.documentMessage?.caption ||
  null;

let mediaType = null;
let mediaUrl = null;
let mediaMimeType = null;
let mediaFileName = null;

if (messagePayload.audioMessage) {
  mediaType = 'audio';
  mediaUrl = messagePayload.audioMessage.url || null;
  mediaMimeType = messagePayload.audioMessage.mimetype || messagePayload.audioMessage.mimeType || 'audio/ogg';
} else if (messagePayload.imageMessage) {
  mediaType = 'image';
  mediaUrl = messagePayload.imageMessage.url || null;
  mediaMimeType = messagePayload.imageMessage.mimetype || messagePayload.imageMessage.mimeType || 'image/jpeg';
} else if (messagePayload.documentMessage) {
  mediaType = 'document';
  mediaUrl = messagePayload.documentMessage.url || null;
  mediaMimeType = messagePayload.documentMessage.mimetype || messagePayload.documentMessage.mimeType || null;
  mediaFileName = messagePayload.documentMessage.fileName || null;
} else if (messagePayload.videoMessage) {
  mediaType = 'video';
  mediaUrl = messagePayload.videoMessage.url || null;
  mediaMimeType = messagePayload.videoMessage.mimetype || messagePayload.videoMessage.mimeType || 'video/mp4';
} else if (messagePayload.stickerMessage) {
  mediaType = 'sticker';
  mediaUrl = messagePayload.stickerMessage.url || null;
  mediaMimeType = messagePayload.stickerMessage.mimetype || messagePayload.stickerMessage.mimeType || 'image/webp';
}

const routeType = mediaType || 'text';

return [{
  json: {
    provider: 'evolution_api',
    event,
    instance_name: instanceName,
    instance_id: instanceId,
    server_url: serverUrl,
    remote_jid: remoteJid,
    remote_jid_alt: remoteJidAlt,

    is_group: isGroup,
    group_jid: groupJid,
    participant_jid: participantJid,
    customer_jid: customerJid,

    sender_identifier: senderIdentifier,
    sender_name: pushName,
    from_me: fromMe,
    provider_message_id: providerMessageId,
    message_type: messageType,
    route_type: routeType,
    content_text: contentText,
    caption_text: captionText,
    message_timestamp: messageTimestamp,
    has_media: Boolean(mediaType),
    media_type: mediaType,
    media_url: mediaUrl,
    media_mime_type: mediaMimeType,
    media_file_name: mediaFileName,

    // Datos resueltos por Streamify antes del procesamiento
    resolved_client: resolved.client || null,
    resolved_service: resolved.service || null,
    resolved_channel: resolved.channel || null,
    resolved_final_customer: resolved.final_customer || null,

    instance: {
      name: instanceName,
      server_url: serverUrl,
      apikey: evoApiKey
    },
    message: {
      id: providerMessageId,
      key,
      type: messageType,
      body: messagePayload
    },
    contact: {
      numero: senderIdentifier,
      nombre: pushName,
      jid: customerJid,
      group_jid: groupJid,
      tipo: isGroup ? 'grupo' : 'cliente_final'
    },

    ignore: isGroup,
    ignore_reason: isGroup ? 'group_message' : null,

    raw_payload: body
  }
}];

const input = $input.first().json || {};
let raw =
  input?.["0"]?.content?.[0]?.text ||
  input?.content?.[0]?.text ||
  input?.message?.content ||
  input?.text ||
  "";

if (typeof raw !== "string") raw = JSON.stringify(raw);

raw = raw.replace(/```json/g, "").replace(/```/g, "").trim();

let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  parsed = {
    tipo: "imagen",
    es_comprobante: false,
    descripcion: raw || "Imagen recibida sin análisis estructurado",
    texto_detectado: "",
    confianza: null
  };
}

const caption = $('Normalizar Evo Payload').first().json.caption_text || "";

const descripcion = parsed.descripcion || "";
const textoDetectado = parsed.texto_detectado || parsed.ocr_text || parsed.content || "";

const agentInput = [
  caption ? `Caption del cliente: ${caption}` : "",
  descripcion ? `Descripción de imagen: ${descripcion}` : "",
  textoDetectado ? `Texto detectado en imagen: ${textoDetectado}` : "",
  parsed.es_comprobante ? `Datos de comprobante: ${JSON.stringify(parsed.datos || parsed.data || parsed.comprobantes || parsed)}` : ""
].filter(Boolean).join("\n\n") || "[Imagen recibida sin texto detectable]";

return [{
  json: {
    processed_type: "image",
    ocr_text: textoDetectado || descripcion || "",
    transcription_text: "",
    image_analysis_json: JSON.stringify(parsed),
    agent_input_text: agentInput
  }
}];

